"""UTC network, directional filters, local boards and shared country projections."""
import os
from playwright.sync_api import sync_playwright


with sync_playwright() as p:
    browser=p.chromium.launch(channel='chrome',headless=True,args=['--enable-unsafe-swiftshader','--use-angle=swiftshader'])
    page=browser.new_page(viewport={'width':1440,'height':1100},ignore_https_errors=True)
    errors=[];downloads=[]
    page.on('pageerror',lambda e:errors.append(str(e)))
    page.on('request',lambda r:downloads.append(r.url) if '/api/replay/' in r.url else None)
    page.goto(os.environ.get('SUNTRAIN_TEST_URL','http://127.0.0.1:8873'),wait_until='domcontentloaded')
    page.wait_for_function('window.dash_clientside && document.querySelector("#replay-panel")')
    page.evaluate('dash_clientside.set_props("view-tabs",{value:"replay"});dash_clientside.set_props("replay-city",{value:"international_network"})')
    page.wait_for_function('window.suntrainReplay?.day?.city==="international_network" && suntrainReplay.mapReady && !suntrainReplay.loading && suntrainReplay.filtered.length && !suntrainReplay.needsFit',timeout=120000)
    assert page.evaluate('suntrainReplay.day.start===Date.UTC(2026,10,2)/1000 && suntrainReplay.day.end===Date.UTC(2026,10,3)/1000')
    assert not page.evaluate('suntrainReplay.frequencyView')
    assert page.locator('#replay-country-controls').is_visible()
    assert not page.locator('#replay-flight-scope-field').is_visible()
    assert 'UTC' in page.locator('#replay-clock-date').inner_text()
    assert page.evaluate('suntrainReplay.filtered.every(s=>s.flight_scope==="international" && suntrainReplay.day.stations[s.stops[0][0]].country!==suntrainReplay.day.stations[s.stops.at(-1)[0]].country)')
    initial_downloads=len(downloads)
    page.screenshot(path='.cache/international-network-audit/map.png')
    for origin,destination in [('CN','JP'),('CN','KR'),('JP','KR'),('SG','AU'),('AE','IN')]:
        page.evaluate('([a,b])=>{dash_clientside.set_props("replay-from-countries",{value:[a]});dash_clientside.set_props("replay-to-countries",{value:[b]})}',[origin,destination])
        page.wait_for_function('([a,b])=>suntrainReplay.filters.fromCountries[0]===a && suntrainReplay.filters.toCountries[0]===b && suntrainReplay.filtered.length && suntrainReplay.filtered.every(s=>suntrainReplay.day.stations[s.stops[0][0]].country===a && suntrainReplay.day.stations[s.stops.at(-1)[0]].country===b)',arg=[origin,destination])
        print(f'{origin} → {destination}: {page.evaluate("suntrainReplay.filtered.length")} flights',flush=True)
    # Same-country selections are valid empty intersections, never domestic leakage.
    page.evaluate('dash_clientside.set_props("replay-from-countries",{value:["JP"]});dash_clientside.set_props("replay-to-countries",{value:["JP"]})')
    page.wait_for_function('suntrainReplay.filters.fromCountries[0]==="JP" && suntrainReplay.filters.toCountries[0]==="JP" && !suntrainReplay.filtered.length')
    page.evaluate('dash_clientside.set_props("replay-from-countries",{value:[]});dash_clientside.set_props("replay-to-countries",{value:[]});dash_clientside.set_props("replay-airports",{value:["NRT"]});dash_clientside.set_props("replay-airport-direction",{value:"departures"})')
    page.wait_for_function('!suntrainReplay.filters.fromCountries.length && !suntrainReplay.filters.toCountries.length && suntrainReplay.filtered.length && suntrainReplay.filtered.every(s=>suntrainReplay.day.stations[s.stops[0][0]].code==="NRT")')
    carrier=page.evaluate('suntrainReplay.filtered[0].carrier')
    page.evaluate('(c)=>dash_clientside.set_props("replay-carriers",{value:[c]})',carrier)
    page.wait_for_function('(c)=>suntrainReplay.filtered.length && suntrainReplay.filtered.every(s=>s.carrier===c)',arg=carrier)
    page.evaluate('dash_clientside.set_props("replay-carriers",{value:[]});suntrainReplay.seek(suntrainReplay.day.start);suntrainReplay.departures.open(suntrainReplay.day.stations.findIndex(a=>a.code==="NRT"))')
    page.wait_for_function('suntrainReplay.departures.services===suntrainReplay.filtered && suntrainReplay.departures.calls.length')
    assert 'JST' in page.locator('#replay-departures').inner_text()
    assert 'UTC' in page.locator('#replay-departures').inner_text()
    assert 'No currency conversion' in page.locator('#replay-departures').inner_text()
    page.get_by_role('button',name='Expand board',exact=True).click()
    next_page=page.get_by_role('button',name='Next',exact=True)
    assert next_page.is_enabled();next_page.click();assert page.evaluate('suntrainReplay.departures.page')==1
    page.get_by_role('button',name='Previous',exact=True).click()
    before=page.evaluate('suntrainReplay.now');page.locator('.departure-row').first.click()
    assert page.evaluate('suntrainReplay.now')==before
    page.get_by_role('button',name='Back to airport board',exact=True).click()
    assert page.evaluate('suntrainReplay.departures.expanded')
    page.locator('[data-event="arrival"]').click()
    page.wait_for_function('suntrainReplay.filters.airportDirection==="arrivals" && suntrainReplay.filtered.length && suntrainReplay.filtered.every(s=>suntrainReplay.day.stations[s.stops.at(-1)[0]].code==="NRT")')
    page.locator('[data-event="destinations"]').click()
    page.wait_for_function('suntrainReplay.departures.destinationRows.length>0')
    page.screenshot(path='.cache/international-network-audit/desktop.png')
    page.evaluate('suntrainReplay.departures.close();dash_clientside.set_props("replay-airports",{value:[]});dash_clientside.set_props("replay-flight-view",{value:"frequency"})')
    page.wait_for_function('suntrainReplay.frequencyView && suntrainReplay.frequencyFeatures.length && !suntrainReplay.filters.airports.length')
    assert page.evaluate('suntrainReplay.frequencyFeatures.reduce((n,f)=>n+f.properties.count,0)===suntrainFlightNetwork.ownedFlights(suntrainReplay.filtered,suntrainReplay.day).length')
    features=page.evaluate('JSON.stringify(suntrainReplay.frequencyFeatures)')
    page.evaluate('suntrainReplay.seek(suntrainReplay.day.end)')
    assert page.evaluate('JSON.stringify(suntrainReplay.frequencyFeatures)')==features
    page.screenshot(path='.cache/international-network-audit/frequency.png')
    page.evaluate('dash_clientside.set_props("replay-display",{value:["routes"]})')
    page.wait_for_function('!suntrainReplay.graph.getSource("replay-stations")._data.features.length')
    page.evaluate('dash_clientside.set_props("replay-display",{value:["routes","stations"]})')
    for theme in ['light','dark','sunrise','blueprint','heritage']:page.locator('#theme-toggle').select_option(theme)
    page.locator('#theme-toggle').select_option('dark')
    assert len(downloads)==initial_downloads
    page.locator('#language-select').select_option('id');page.wait_for_function('document.documentElement.lang==="id"')
    assert 'Dari negara' in page.locator('#replay-country-controls').inner_text()
    assert page.locator('#replay-from-countries').get_attribute('placeholder')=='Semua negara' or 'Semua negara' in page.locator('#replay-from-countries').inner_text()
    page.set_viewport_size({'width':390,'height':844})
    assert page.evaluate('document.documentElement.scrollWidth<=innerWidth')
    page.evaluate('suntrainReplay.departures.open(suntrainReplay.day.stations.findIndex(a=>a.code==="NRT"));suntrainReplay.departures.setExpanded(true)')
    page.wait_for_function('document.querySelector(".replay-detail-card").getBoundingClientRect().height===innerHeight && document.querySelector(".replay-detail-card").getBoundingClientRect().top===0')
    page.evaluate('() => new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)))')
    page.screenshot(path='.cache/international-network-audit/mobile.png')
    page.evaluate('suntrainReplay.departures.close()');page.set_viewport_size({'width':1440,'height':1100})
    page.locator('#language-select').select_option('en')
    for city,zone in [('china_flights','Asia/Shanghai'),('japan_flights','Asia/Tokyo'),('south_korea_flights','Asia/Seoul')]:
        page.evaluate('(city)=>dash_clientside.set_props("replay-city",{value:city})',city)
        page.wait_for_function('(city)=>suntrainReplay.day.city===city && !suntrainReplay.loading && suntrainReplay.filtered.length && suntrainReplay.filters.flightScope==="domestic"',arg=city,timeout=120000)
        assert page.locator('#replay-flight-scope-field').is_visible()
        assert not page.locator('#replay-country-controls').is_visible()
        assert page.evaluate('suntrainReplay.filtered.every(s=>s.flight_scope==="domestic")')
        assert page.evaluate('suntrainReplay.day.timezone')==zone
        page.evaluate('dash_clientside.set_props("replay-flight-scope",{value:"international"})')
        page.wait_for_function('suntrainReplay.filters.flightScope==="international" && suntrainReplay.filtered.length && suntrainReplay.filtered.every(s=>s.flight_scope==="international")')
        page.evaluate('dash_clientside.set_props("replay-flight-scope",{value:"both"})')
        page.wait_for_function('suntrainReplay.filters.flightScope==="both" && new Set(suntrainReplay.filtered.map(s=>s.flight_scope)).size===2')
        assert page.evaluate('!suntrainReplay.filters.fromCountries.length && !suntrainReplay.filters.toCountries.length')
        print(city,'domestic/international/both, local clock and filter reset passed',flush=True)
    assert not errors,errors
    print('UTC network, all three new country pairs, exact airport/carrier filtering, local boards, fullscreen/back, frequency, themes, Indonesian and mobile passed',flush=True)
    browser.close()
